SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "追述张延朗尽收河东应留使之外财赋，石敬瑭怀恨。", "citation": "卷280·后唐清泰三年／后晋天福元年（936；闰十一月条下）·zztj-v280-y0936-p054·原文件第59行", "note": "原文：初，帝在河东，为唐朝所忌，中书侍郎、同平章事、判三司张延朗不欲河东多蓄积，凡财赋应留使之外尽收取之，帝以是恨之。；核对说明：初为此前积怨，不把全部多年财赋征收归到936甲申当日。应留使之外限定不略。", "status": "draft", "id": "25bf6017-af9c-5e71-a779-fd2fff033eed", "subject_id": "f78c6dae-028b-5027-ba98-cca1c61a34d6", "source_id": "2c2d0394-a332-5016-8a20-7b21040dbdb2"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "石敬瑭在河东、唐朝猜忌时追叙；独立年日未载", "citation": "卷280·后唐清泰三年／后晋天福元年（936；闰十一月条下）·zztj-v280-y0936-p054·原文件第59行", "note": "原文：初，帝在河东，为唐朝所忌，中书侍郎、同平章事、判三司张延朗不欲河东多蓄积，凡财赋应留使之外尽收取之，帝以是恨之。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "bb52aee3-dda3-546a-8a02-1140d97b52c5", "subject_id": "f78c6dae-028b-5027-ba98-cca1c61a34d6", "source_id": "2c2d0394-a332-5016-8a20-7b21040dbdb2"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记石敬瑭：河东受限制、记恨者。", "citation": "卷280·后唐清泰三年／后晋天福元年（936；闰十一月条下）·zztj-v280-y0936-p054·原文件第59行", "note": "原文：初，帝在河东，为唐朝所忌，中书侍郎、同平章事、判三司张延朗不欲河东多蓄积，凡财赋应留使之外尽收取之，帝以是恨之。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "c171e27a-07ec-5695-97eb-814c7fdf99c8", "subject_id": "bf42d98c-7477-5be1-a767-867fe26cf617", "source_id": "2c2d0394-a332-5016-8a20-7b21040dbdb2"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "石敬瑭：河东受限制、记恨者。", "citation": "卷280·后唐清泰三年／后晋天福元年（936；闰十一月条下）·zztj-v280-y0936-p054·原文件第59行", "note": "原文：初，帝在河东，为唐朝所忌，中书侍郎、同平章事、判三司张延朗不欲河东多蓄积，凡财赋应留使之外尽收取之，帝以是恨之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "8b231b7c-ddc9-5f64-9e13-c13744312779", "subject_id": "2f7a4dcc-7482-5c02-9deb-1fab33142715", "source_id": "2c2d0394-a332-5016-8a20-7b21040dbdb2"}, {"subject_table": "person", "field_path": "descript